#include <stdio.h>

struct Rect {
    int width;
    int height;
};

int area(const struct Rect *r) {
    return r->width * r->height;
}

int main() {
    struct Rect r = {6, 7};
    printf("Area: %d\n", area(&r));
    return 0;
}
